{{
  (() => {
    const cat = Get_Suivi_Client.data[0]?.Categorie_Materiel || '4T';
    const joursPresents = Get_Suivi_Client.data[0]?.Jours_Dans_Atelier || 0;
    const rowDelai = (Get_Delai_Moyen.data || []).find(r => r.Categorie_Materiel === cat);
    const delaiMoyen = rowDelai?.Delai_Moyen_Jours || 7;
    const resteJours = delaiMoyen - joursPresents;

    if (resteJours <= 1) {
      return "⏳ Prise en charge imminente : votre matériel arrive en tête de file d'attente à l'atelier.";
    }

    return "⏳ Délai estimé : encore environ " + resteJours + " jour" + (resteJours > 1 ? "s" : "") + " avant intervention sur votre matériel (" + cat + ").\n(Délai moyen atelier : " + delaiMoyen + " jours — Déposé il y a " + joursPresents + " jours).";
  })()
}}
